import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';

function EditSupplierForm({ getSuppliers, updateSupplier }) {
    const { id } = useParams();
    const supplierId = Number(id);
    const navigate = useNavigate();
    const [supplier, setSupplier] = useState(null);

    useEffect(() => {
        getSuppliers().then((suppliers) => {
            console.log("Fetched suppliers", suppliers); // Debugging
            const foundSupplier = suppliers.find(s => s.id === supplierId); //Id matching
            if (foundSupplier) {
                setSupplier(foundSupplier);
            } else {
                console.error("No supplier found with id:", id);
            }
        });
    }, [id, getSuppliers]);

    const handleChange = (e) => {
        setSupplier({...supplier, [e.target.name]: e.target.value });
    };

    const handleSubmit = (e) => {
        e.preventDefault();
        updateSupplier(supplier);
        setTimeout(() => navigate('/suppliers'), 100); // waiting for update
    };

    if (!supplier) return <p>Loading...</p>

    return (
        <form onSubmit={handleSubmit}>
            <h1>Edit Supplier</h1>
            <div className='formField'>
                <label>Company Name:</label>
                <input type="text" name="name" value={supplier.name} onChange={handleChange} className='shortInputField' />
            </div>
            <div className='formField'>
                <label>Contact Person:</label>
                <input type="text" name="contact" value={supplier.contact} onChange={handleChange} className='longInputField' />
            </div>
            <div className='twoFieldsHolder'>
                <div className='formField'>
                    <label>Website:</label>
                    <input type="text" name="website" value={supplier.website} onChange={handleChange}  className='longInputField' />
                </div>
                <div className='formField'>
                    <label>Phone:</label>
                    <input type="text" name="phone" value={supplier.phone} onChange={handleChange} className='shortInputField' />
                </div>
            </div>
            <div className='formField'>
                <label>Email:</label>
                <input type="text" name="email" value={supplier.email} onChange={handleChange}className='longInputField' />
            </div>
            <div className='formField'>
                <label>Street:</label>
                <input type="text" name="street" value={supplier.street} onChange={handleChange} className='longInputField' />
            </div>
            <div className='twoFieldsHolder'>
                <div className='formField'>
                    <label>City:</label>
                    <input type="text" name="city" value={supplier.city} onChange={handleChange} className='shortInputField' />
                </div>
                <div className='formField'>
                    <label>Postal Code:</label>
                    <input type="text" name="postal code" value={supplier.postalCode} onChange={handleChange} className='shortInputField' />
                </div>
            </div>
            <div className='formField'>
                <label>Country:</label>
                <input type="text" name="country" value={supplier.country} onChange={handleChange} className='shortInputField' />
            </div>
            <div className='formField'>
                <label>Additional Notes:</label>
                <input type="text" name="notes" value={supplier.notes} onChange={handleChange} className='longInputField' />
            </div>
            
            
            <button className="addBtn" type="submit">Save Changes</button>
        </form>
    );
}

export default EditSupplierForm;
